.tvx a{color:inherit;text-decoration:none}
.tvx{width:100%;min-width:1440px;color:#1C1C1E;font-family:ui-rounded,'SF Pro Rounded',-apple-system,BlinkMacSystemFont,system-ui,sans-serif;font-weight:600}
.tvx .word{margin:0;font-family:'Gasoek One',sans-serif;font-weight:400;font-size:120px;line-height:.92;letter-spacing:.005em;text-transform:uppercase}
.tvx .tag{margin:14px 0 0;font-size:30px;font-weight:600;line-height:1.2;letter-spacing:-.01em}
.tvx .body{margin:14px 0 0;font-size:18px;font-weight:600;line-height:1.45;color:rgba(28,28,30,.62)}
.tvx .cloud{position:absolute;width:130px;height:42px;background:#fff;border-radius:999px;opacity:.95;filter:drop-shadow(0 10px 24px rgba(40,30,90,.14));transform-origin:left center;animation:tv-cdrift 11s ease-in-out infinite alternate;z-index:1;pointer-events:none}
.tvx .cloud::before,.tvx .cloud::after{content:'';position:absolute;background:#fff;border-radius:50%}
.tvx .cloud::before{width:52px;height:52px;top:-26px;left:22px}
.tvx .cloud::after{width:38px;height:38px;top:-18px;left:64px}
@keyframes tv-cdrift{from{translate:0 0}to{translate:26px -6px}}
.tvx .sec{position:relative;overflow:hidden;overflow:clip visible}
.tvx .in{position:relative;width:1440px;height:100%;margin:0 auto}
.tvx .eyebrow{font-family:'JetBrains Mono',monospace;font-size:12px;font-weight:700;letter-spacing:.2em;color:#6B6585}
.tvx .h2{margin:16px 0 0;font-weight:800;font-size:64px;line-height:1;letter-spacing:-.045em}
.tvx .h2 em{display:block;font-family:'Instrument Serif',serif;font-weight:400;font-style:italic;letter-spacing:-.02em;font-size:72px;color:#2774FD;line-height:1}
.tvx .lead{margin:22px 0 0;font-size:20px;line-height:1.45;color:#4A4468}
.tvx .store{display:inline-flex;align-items:center;gap:6px;height:54px;padding:0 24px 0 18px;border-radius:999px;background:#000;color:#fff;font-weight:600;font-size:17px}
.tvx .badge{display:inline-flex;flex-shrink:0}
.tvx .badge img{height:54px;width:auto;display:block}
.tvx .rating{display:inline-flex;align-items:center;gap:8px;font-size:15px;font-weight:600;color:rgba(28,28,30,.7)}
.tvx .stars{display:inline-flex;color:#E8A400}
.tvx .appf{font-family:ui-rounded,'SF Pro Rounded',-apple-system,BlinkMacSystemFont,system-ui,sans-serif;color:#1C1C1E}
@keyframes tv-caret{50%{opacity:0}}
@keyframes tv-ring{0%{transform:scale(1);opacity:.8}100%{transform:scale(2.6);opacity:0}}
@keyframes tv-bob1{0%,100%{transform:translateY(0) rotate(-1.2deg)}50%{transform:translateY(-10px) rotate(-.4deg)}}
@keyframes tv-bob2{0%,100%{transform:translateY(0) rotate(1deg)}50%{transform:translateY(-8px) rotate(.3deg)}}
@keyframes tv-grow{0%{transform:scaleY(.05)}14%,86%{transform:scaleY(1)}100%{transform:scaleY(.05)}}
@keyframes tv-march{to{stroke-dashoffset:-22}}
